using Microsoft.EntityFrameworkCore;

// Cosmos DB project context - migrated to EF Core 9
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<DiscountedProduct> DiscountedProducts => Set<DiscountedProduct>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // BREAKING CHANGE FIX #1: EF Core 9 Cosmos provider now uses "$type"
            // instead of "Discriminator" by default. Since we have existing documents
            // with "Discriminator", we must explicitly configure it to maintain
            // backward compatibility.
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Product>("Product")
                .HasValue<DiscountedProduct>("DiscountedProduct");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
    public decimal Price { get; set; }
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

using Microsoft.EntityFrameworkCore;

// BREAKING CHANGE FIX #2: EF Core 9 Cosmos provider removed synchronous I/O
// (e.g., ToList(), First(), Count()). All queries must use async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Before (EF Core 8 - synchronous, now throws InvalidOperationException):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();
    //   var first = _db.Products.First(p => p.Id == id);
    //   var count = _db.Products.Count();

    // After (EF Core 9 - async required):
    public async Task<List<Product>> GetProductsByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task<Product> GetProductByIdAsync(string id)
    {
        return await _db.Products
            .FirstAsync(p => p.Id == id);
    }

    public async Task<int> GetProductCountAsync()
    {
        return await _db.Products.CountAsync();
    }
}

